-- ============================================================
-- PART 2: CREATE NEW TABLES
-- ============================================================

-- -------------------------------------------------------
-- 1. CARDS
-- Stores debit and credit cards linked to accounts
-- -------------------------------------------------------
CREATE TABLE CARDS (
    card_id       NUMBER PRIMARY KEY,
    account_id    NUMBER REFERENCES ACCOUNTS(account_id),
    card_type     VARCHAR2(10),    -- DEBIT / CREDIT
    card_number   VARCHAR2(20),    -- masked format: XXXX-XXXX-XXXX-1234
    expiry_date   DATE,
    status        VARCHAR2(10),    -- ACTIVE / BLOCKED / EXPIRED
    credit_limit  NUMBER(10,2),    -- NULL for debit cards
    issued_date   DATE
);

 
-- -------------------------------------------------------
-- 2. TRANSFERS
-- Records money movements between accounts
-- -------------------------------------------------------
CREATE TABLE TRANSFERS (
    transfer_id      NUMBER PRIMARY KEY,
    from_account_id  NUMBER REFERENCES ACCOUNTS(account_id),
    to_account_id    NUMBER REFERENCES ACCOUNTS(account_id),
    amount           NUMBER(10,2),
    transfer_date    DATE,
    description      VARCHAR2(100),
    status           VARCHAR2(10)   -- COMPLETED / PENDING / FAILED
);

 
-- -------------------------------------------------------
-- 3. BENEFICIARIES
-- Saved recipients for transfers and standing orders
-- -------------------------------------------------------
CREATE TABLE BENEFICIARIES (
    beneficiary_id   NUMBER PRIMARY KEY,
    customer_id      NUMBER REFERENCES CUSTOMERS(customer_id),
    beneficiary_name VARCHAR2(60),
    account_number   VARCHAR2(20),
    bank_name        VARCHAR2(50),
    nickname         VARCHAR2(30),
    created_date     DATE
);

 
-- -------------------------------------------------------
-- 4. FEES
-- Charges applied to accounts (maintenance, overdraft, etc.)
-- -------------------------------------------------------
CREATE TABLE FEES (
    fee_id       NUMBER PRIMARY KEY,
    account_id   NUMBER REFERENCES ACCOUNTS(account_id),
    fee_type     VARCHAR2(30),    -- MAINTENANCE / OVERDRAFT / TRANSFER / ATM / LATE_PAYMENT
    amount       NUMBER(8,2),
    fee_date     DATE,
    description  VARCHAR2(100),
    status       VARCHAR2(10)    -- PAID / PENDING / WAIVED
);

-- -------------------------------------------------------
-- 5. AUDIT_LOG
-- Tracks all changes made to any table record
-- -------------------------------------------------------
CREATE TABLE AUDIT_LOG (
    log_id       NUMBER PRIMARY KEY,
    table_name   VARCHAR2(30),
    operation    VARCHAR2(10),   -- INSERT / UPDATE / DELETE
    record_id    NUMBER,
    changed_by   VARCHAR2(30),
    change_date  DATE,
    old_value    VARCHAR2(200),
    new_value    VARCHAR2(200)
);

 
-- -------------------------------------------------------
-- 6. LOAN_PAYMENTS
-- Monthly payment history for each loan
-- -------------------------------------------------------
CREATE TABLE LOAN_PAYMENTS (
    payment_id         NUMBER PRIMARY KEY,
    loan_id            NUMBER REFERENCES LOANS(loan_id),
    payment_date       DATE,
    amount             NUMBER(10,2),
    principal_paid     NUMBER(10,2),
    interest_paid      NUMBER(10,2),
    remaining_balance  NUMBER(12,2),
    status             VARCHAR2(10)   -- PAID / MISSED / PENDING
);

 
-- -------------------------------------------------------
-- 7. STANDING_ORDERS
-- Scheduled recurring payments
-- -------------------------------------------------------
CREATE TABLE STANDING_ORDERS (
    order_id             NUMBER PRIMARY KEY,
    account_id           NUMBER REFERENCES ACCOUNTS(account_id),
    beneficiary_id       NUMBER REFERENCES BENEFICIARIES(beneficiary_id),
    amount               NUMBER(10,2),
    frequency            VARCHAR2(10),   -- MONTHLY / WEEKLY / DAILY
    next_execution_date  DATE,
    status               VARCHAR2(10),   -- ACTIVE / PAUSED / CANCELLED
    description          VARCHAR2(100)
);

 
 
-- -------------------------------------------------------
-- 8. ATM_MACHINES
-- ATM locations linked to branches
-- -------------------------------------------------------
CREATE TABLE ATM_MACHINES (
    atm_id           NUMBER PRIMARY KEY,
    branch_id        NUMBER REFERENCES BRANCHES(branch_id),
    location         VARCHAR2(100),
    address          VARCHAR2(100),
    status           VARCHAR2(15),  -- ACTIVE / OUT_OF_SERVICE / MAINTENANCE
    last_maintenance DATE,
    cash_available   NUMBER(12,2)
);

 
COMMIT;

